
create table if not exists pessoas_fundidas (id uuid primary key, fundida_em uuid not null, dados jsonb not null, em timestamptz default now());
alter table pessoas_fundidas enable row level security;
create policy equipa_all on pessoas_fundidas for all to authenticated using (is_equipa()) with check (is_equipa());

create or replace function fundir_pessoas(fica uuid, sai uuid[]) returns void language plpgsql security definer set search_path=public as $f$
declare um uuid;
begin
  insert into pessoas_fundidas (id,fundida_em,dados) select o.id, fica, to_jsonb(o) from pessoas o where o.id=any(sai) on conflict (id) do nothing;
  update pessoas p set nome=coalesce(p.nome,(select o.nome from pessoas o where o.id=any(sai) and o.nome is not null order by o.updated_at desc nulls last limit 1)), nasc=coalesce(p.nasc,(select o.nasc from pessoas o where o.id=any(sai) and o.nasc is not null order by o.updated_at desc nulls last limit 1)), sexo=coalesce(p.sexo,(select o.sexo from pessoas o where o.id=any(sai) and o.sexo is not null order by o.updated_at desc nulls last limit 1)), nac=coalesce(p.nac,(select o.nac from pessoas o where o.id=any(sai) and o.nac is not null order by o.updated_at desc nulls last limit 1)), nat=coalesce(p.nat,(select o.nat from pessoas o where o.id=any(sai) and o.nat is not null order by o.updated_at desc nulls last limit 1)), doc_tipo=coalesce(p.doc_tipo,(select o.doc_tipo from pessoas o where o.id=any(sai) and o.doc_tipo is not null order by o.updated_at desc nulls last limit 1)), doc_num=coalesce(p.doc_num,(select o.doc_num from pessoas o where o.id=any(sai) and o.doc_num is not null order by o.updated_at desc nulls last limit 1)), doc_val=greatest(p.doc_val,(select max(doc_val) from pessoas o where o.id=any(sai))), nif=coalesce(p.nif,(select o.nif from pessoas o where o.id=any(sai) and o.nif is not null order by o.updated_at desc nulls last limit 1)), nss=coalesce(p.nss,(select o.nss from pessoas o where o.id=any(sai) and o.nss is not null order by o.updated_at desc nulls last limit 1)), pass_fin=coalesce(p.pass_fin,(select o.pass_fin from pessoas o where o.id=any(sai) and o.pass_fin is not null order by o.updated_at desc nulls last limit 1)), morada=coalesce(p.morada,(select o.morada from pessoas o where o.id=any(sai) and o.morada is not null order by o.updated_at desc nulls last limit 1)), cp=coalesce(p.cp,(select o.cp from pessoas o where o.id=any(sai) and o.cp is not null order by o.updated_at desc nulls last limit 1)), loc=coalesce(p.loc,(select o.loc from pessoas o where o.id=any(sai) and o.loc is not null order by o.updated_at desc nulls last limit 1)), tel=coalesce(p.tel,(select o.tel from pessoas o where o.id=any(sai) and o.tel is not null order by o.updated_at desc nulls last limit 1)), telalt=coalesce(p.telalt,(select o.telalt from pessoas o where o.id=any(sai) and o.telalt is not null order by o.updated_at desc nulls last limit 1)), email=coalesce(p.email,(select o.email from pessoas o where o.id=any(sai) and o.email is not null order by o.updated_at desc nulls last limit 1)), carta_num=coalesce(p.carta_num,(select o.carta_num from pessoas o where o.id=any(sai) and o.carta_num is not null order by o.updated_at desc nulls last limit 1)), carta_cats=coalesce(p.carta_cats,(select o.carta_cats from pessoas o where o.id=any(sai) and o.carta_cats is not null order by o.updated_at desc nulls last limit 1)), carta_vg1=greatest(p.carta_vg1,(select max(carta_vg1) from pessoas o where o.id=any(sai))), carta_vg2=greatest(p.carta_vg2,(select max(carta_vg2) from pessoas o where o.id=any(sai))), srv=coalesce(p.srv,(select o.srv from pessoas o where o.id=any(sai) and o.srv is not null order by o.updated_at desc nulls last limit 1)), indicado=coalesce(p.indicado,(select o.indicado from pessoas o where o.id=any(sai) and o.indicado is not null order by o.updated_at desc nulls last limit 1)), parceiro=coalesce(p.parceiro,(select o.parceiro from pessoas o where o.id=any(sai) and o.parceiro is not null order by o.updated_at desc nulls last limit 1)), estado=coalesce(p.estado,(select o.estado from pessoas o where o.id=any(sai) and o.estado is not null order by o.updated_at desc nulls last limit 1)), data_fim_formacao=greatest(p.data_fim_formacao,(select max(data_fim_formacao) from pessoas o where o.id=any(sai))), data_averbamento=coalesce(p.data_averbamento,(select o.data_averbamento from pessoas o where o.id=any(sai) and o.data_averbamento is not null order by o.updated_at desc nulls last limit 1)), data_ultima_psi=greatest(p.data_ultima_psi,(select max(data_ultima_psi) from pessoas o where o.id=any(sai))), curso=coalesce(p.curso,(select o.curso from pessoas o where o.id=any(sai) and o.curso is not null order by o.updated_at desc nulls last limit 1)), opt_out_data=coalesce(p.opt_out_data,(select o.opt_out_data from pessoas o where o.id=any(sai) and o.opt_out_data is not null order by o.updated_at desc nulls last limit 1)), carta_cats_g1=coalesce(p.carta_cats_g1,(select o.carta_cats_g1 from pessoas o where o.id=any(sai) and o.carta_cats_g1 is not null order by o.updated_at desc nulls last limit 1)), carta_cats_g2=coalesce(p.carta_cats_g2,(select o.carta_cats_g2 from pessoas o where o.id=any(sai) and o.carta_cats_g2 is not null order by o.updated_at desc nulls last limit 1)), carta_emitida=coalesce(p.carta_emitida,(select o.carta_emitida from pessoas o where o.id=any(sai) and o.carta_emitida is not null order by o.updated_at desc nulls last limit 1)), carta_restricoes=coalesce(p.carta_restricoes,(select o.carta_restricoes from pessoas o where o.id=any(sai) and o.carta_restricoes is not null order by o.updated_at desc nulls last limit 1)), modalidade=coalesce(p.modalidade,(select o.modalidade from pessoas o where o.id=any(sai) and o.modalidade is not null order by o.updated_at desc nulls last limit 1)), turma=coalesce(p.turma,(select o.turma from pessoas o where o.id=any(sai) and o.turma is not null order by o.updated_at desc nulls last limit 1)), habilitacoes=coalesce(p.habilitacoes,(select o.habilitacoes from pessoas o where o.id=any(sai) and o.habilitacoes is not null order by o.updated_at desc nulls last limit 1)), habilitacoes_curso=coalesce(p.habilitacoes_curso,(select o.habilitacoes_curso from pessoas o where o.id=any(sai) and o.habilitacoes_curso is not null order by o.updated_at desc nulls last limit 1)), situacao_prof=coalesce(p.situacao_prof,(select o.situacao_prof from pessoas o where o.id=any(sai) and o.situacao_prof is not null order by o.updated_at desc nulls last limit 1)), categoria_prof=coalesce(p.categoria_prof,(select o.categoria_prof from pessoas o where o.id=any(sai) and o.categoria_prof is not null order by o.updated_at desc nulls last limit 1)), local_trabalho=coalesce(p.local_trabalho,(select o.local_trabalho from pessoas o where o.id=any(sai) and o.local_trabalho is not null order by o.updated_at desc nulls last limit 1)), como_conheceu=coalesce(p.como_conheceu,(select o.como_conheceu from pessoas o where o.id=any(sai) and o.como_conheceu is not null order by o.updated_at desc nulls last limit 1)), interesses_formacao=coalesce(p.interesses_formacao,(select o.interesses_formacao from pessoas o where o.id=any(sai) and o.interesses_formacao is not null order by o.updated_at desc nulls last limit 1)), carta_emissao=coalesce(p.carta_emissao,(select o.carta_emissao from pessoas o where o.id=any(sai) and o.carta_emissao is not null order by o.updated_at desc nulls last limit 1)), consent_rgpd_em=greatest(p.consent_rgpd_em,(select max(consent_rgpd_em) from pessoas o where o.id=any(sai))), consent_email=coalesce(p.consent_email,(select o.consent_email from pessoas o where o.id=any(sai) and o.consent_email is not null order by o.updated_at desc nulls last limit 1)), consent_whatsapp=coalesce(p.consent_whatsapp,(select o.consent_whatsapp from pessoas o where o.id=any(sai) and o.consent_whatsapp is not null order by o.updated_at desc nulls last limit 1)), consent_em=greatest(p.consent_em,(select max(consent_em) from pessoas o where o.id=any(sai))), consent_origem=coalesce(p.consent_origem,(select o.consent_origem from pessoas o where o.id=any(sai) and o.consent_origem is not null order by o.updated_at desc nulls last limit 1)),
    opt_out = coalesce(p.opt_out,false) or coalesce((select bool_or(opt_out) from pessoas o where o.id=any(sai)),false),
    obs = nullif(concat_ws(' | ', p.obs, (select string_agg(distinct o.obs,' | ') from pessoas o where o.id=any(sai) and o.obs is not null and o.obs<>coalesce(p.obs,''))),''),
    obs_interna = concat_ws(E'\n', p.obs_interna, (select string_agg(o.obs_interna,E'\n') from pessoas o where o.id=any(sai) and o.obs_interna is not null),
      'Fichas juntas em '||to_char(now(),'DD/MM/YYYY')||': '||(select string_agg(coalesce(o.pid,'sem nº'),', ') from pessoas o where o.id=any(sai)))
  where p.id=fica;
  foreach um in array sai loop
  update consultas_psi set pessoa_id=fica where pessoa_id=um; update faturas set pessoa_id=fica where pessoa_id=um; update emails_log set pessoa_id=fica where pessoa_id=um; update alertas set pessoa_id=fica where pessoa_id=um; update reclamacoes set pessoa_id=fica where pessoa_id=um; update marcacoes_psi set pessoa_id=fica where pessoa_id=um; update codigos_formando set pessoa_id=fica where pessoa_id=um;
  update inscricoes i set pessoa_id=fica where pessoa_id=um and not exists (select 1 from inscricoes j where j.pessoa_id=fica and j.turma_id=i.turma_id);
  update certificados c set pessoa_id=fica where pessoa_id=um and not exists (select 1 from certificados d where d.pessoa_id=fica and d.tipo=c.tipo and d.concluido_em=c.concluido_em);
  update lembretes_enviados l set pessoa_id=fica where pessoa_id=um and not exists (select 1 from lembretes_enviados m where m.pessoa_id=fica and m.tipo=l.tipo and m.validade=l.validade and m.marco=l.marco);
  end loop;
  delete from pessoas where id=any(sai);
end $f$;
revoke all on function fundir_pessoas(uuid,uuid[]) from public, anon, authenticated;
